//! Compiles the vendored grammars under `vendor/grammars/` into the binary. Each `parser.c` is generated by the tree-sitter
//! CLI, so the C compiler's warnings are upstream's and are not shown. A grammar with a `scanner.c` gets it too.

fn main() {
    for (name, has_scanner) in [("vimdoc", false), ("luadoc", false), ("luap", false), ("just", true)] {
        let dir = format!("vendor/grammars/{name}/src");
        println!("cargo:rerun-if-changed={dir}");
        let mut build = cc::Build::new();
        build.include(&dir).file(format!("{dir}/parser.c")).std("c11").warnings(false);
        if has_scanner {
            build.file(format!("{dir}/scanner.c"));
        }
        build.compile(&format!("vendored_{name}"));
    }
    println!("cargo:rerun-if-changed=build.rs");
}
